export const TutorialUpdateSchema = {
  properties: {
    title: {
      anyOf: [
        {
          type: "string",
          maxLength: 255,
          minLength: 1,
        },
        {
          type: "null",
        },
      ],
      title: "Title",
    },
    overview: {
      anyOf: [
        {
          type: "string",
          maxLength: 200000,
        },
        {
          type: "null",
        },
      ],
      title: "Overview",
    },
    level: {
      anyOf: [
        {
          $ref: "#/components/schemas/TutorialLevel",
        },
        {
          type: "null",
        },
      ],
    },
    overview_diagram_mermaid: {
      anyOf: [
        {
          type: "string",
          maxLength: 50000,
        },
        {
          type: "null",
        },
      ],
      title: "Overview Diagram Mermaid",
    },
  },
  type: "object",
  title: "TutorialUpdate",
  description: `All fields optional — this is a partial update.

\`level\` is typed as the enum rather than \`str\`. The old handler took a string,
called \`.upper()\` on it and wrote \`"BEGINNER"\`, which the \`ck_tutorials_level\`
CHECK constraint rejects — so every save including a level returned a 500.
Pydantic now rejects an unknown level with a 422 that names the field, and a
valid one can only be written in the stored lowercase form.`,
} as const;

